import urllib.request,json
for repo in ['bioconductor-deseq2','bioconductor-deseq2-split']:
    url=f'https://quay.io/api/v1/repository/biocontainers/{repo}/tag/?limit=20'
    try:
        with urllib.request.urlopen(url, timeout=20) as r:
            data=json.load(r)
        print(repo)
        for t in data.get('tags',[])[:10]:
            print(' ', t.get('name'))
    except Exception as e:
        print(repo, type(e).__name__, e)
